function sanitizeSession(g) {
 try {
  if(!g||![5,6].includes(g.version)||!UNIT.has(g.unit)||!MODES.includes(g.mode)||!LANGS.includes(g.target)||!LANGS.includes(g.support)||g.route!==`${g.support}>${g.target}`)return null;
  if(typeof g.id!=='string'||g.id.length>80||!['playing','roundDone'].includes(g.phase))return null;
  if(!Array.isArray(g.pool)||g.pool.length<1||g.pool.length>26||g.pool.some(id=>!ITEM.has(id)))return null;
  if(!Array.isArray(g.board)||!g.board.length||g.board.length>120)return null;
  const ids=new Set(),positions=new Set();
  for(const tile of g.board){
   if(!Number.isInteger(tile.id)||tile.id<0||ids.has(tile.id)||!g.pool.includes(tile.itemId)||!LANGS.includes(tile.lang)||!Number.isInteger(tile.x)||tile.x<0||tile.x>10||!Number.isInteger(tile.y)||tile.y<0||tile.y>30||![0,1,2,3].includes(tile.z)||typeof tile.gone!=='boolean'||!['target','support','word'].includes(tile.type)||typeof tile.text!=='string'||tile.text.length>200)return null;
   const item=ITEM.get(tile.itemId);
   if(tile.type==='target'&&(tile.lang!==g.target||tile.text!==item.text[g.target]))return null;
   if(tile.type==='support'&&(tile.lang!==g.support||tile.text!==supportText(item,g.target,g.support)))return null;
   if(tile.type==='word'&&(tile.lang!==g.target||!tokens(item.text[g.target]).includes(tile.text)))return null;
   const at=`${tile.x}:${tile.y}:${tile.z}`;if(positions.has(at))return null;ids.add(tile.id);positions.add(at);
  }
  if(!Array.isArray(g.completed)||g.completed.some(id=>!g.pool.includes(id))||new Set(g.completed).size!==g.completed.length)return null;
  if(!Array.isArray(g.results)||g.results.length>26||g.results.some(r=>!r||!g.pool.includes(r.itemId)||!Number.isFinite(r.mistakes)))return null;
  if(!Array.isArray(g.prefix)||g.prefix.length>120||g.prefix.some(x=>!x||!ids.has(x.id)||typeof x.text!=='string'||x.text.length>200))return null;
  if(!g.helpUses||!['hint','shuffle'].every(k=>Number.isInteger(g.helpUses[k])&&g.helpUses[k]>=0&&g.helpUses[k]<=10000))return null;
  if(!['score','combo','bestCombo','errors','tries','round'].every(k=>Number.isFinite(g[k])&&g[k]>=0&&g[k]<=100000))return null;
  if(!g.assist||!g.mistakes||typeof g.assist!=='object'||typeof g.mistakes!=='object')return null;
  if(g.sentenceVersion!=null&&g.sentenceVersion!==2)return null;if(g.sentenceVersion===2&&(!['complete','compose'].includes(g.mode)||!Array.isArray(g.usedSentences)||g.usedSentences.length>5||g.usedSentences.some(x=>typeof x!=='string'||x.length>600)||!['sentence','pair'].includes(g.labAction)))return null;
  const out=clone(g);out.version=6;out.history=[];out.tableFormat=Object.hasOwn(TABLE_FORMATS,g.tableFormat)?g.tableFormat:'classic';out.challengeDay=/^\d{4}-\d{2}-\d{2}$/.test(g.challengeDay)?g.challengeDay:null;out.seed=Number.isInteger(g.seed)?g.seed>>>0:0;out.tourId=typeof g.tourId==='string'&&/^[a-z0-9_]{1,80}$/.test(g.tourId)?g.tourId:null;out.tourStage=Number.isInteger(g.tourStage)&&g.tourStage>=0&&g.tourStage<3?g.tourStage:null;out.tutorial=Boolean(g.tutorial);out.inviteTarget=Number.isFinite(g.inviteTarget)?Math.max(0,Math.min(10000,g.inviteTarget)):null;
  for(const k of ['heard','revealed'])out[k]=Array.isArray(g[k])?[...new Set(g[k].filter(id=>g.pool.includes(id)))]:[];
  out.hints=Array.isArray(g.hints)?g.hints.filter(id=>ids.has(id)):[];
  out.assist={};out.mistakes={};for(const id of g.pool){if(g.assist[id])out.assist[id]=true;if(Number.isFinite(g.mistakes[id]))out.mistakes[id]=Math.min(10000,Math.max(0,Math.floor(g.mistakes[id])));}
  out.pairSelected=ids.has(g.pairSelected)?g.pairSelected:null;
  if(g.sentenceVersion===2&&g.mode==='compose'){if(new Set(g.prefix.map(p=>p.id)).size!==g.prefix.length||g.prefix.some(p=>{const tile=g.board.find(t=>t.id===p.id);return !tile.gone||tile.text!==p.text;}))return null;for(let i=0;i<out.prefix.length;i++)out.history.push(clone({board:out.board.map(tile=>({...tile,gone:out.prefix.slice(i).some(p=>p.id===tile.id)?false:tile.gone})),prefix:out.prefix.slice(0,i),pairSelected:null,completed:out.completed,results:out.results,score:out.score,combo:out.combo,round:out.round,phase:out.phase,usedSentences:out.usedSentences}));}
  if(g.helpPending){const h=g.helpPending;if(!['hint','shuffle'].includes(h.kind)||!ITEM.has(h.itemId))return null;out.helpPending={kind:h.kind,itemId:h.itemId,tries:Math.max(0,Math.min(10000,Number(h.tries)||0)),answer:String(h.answer||'').slice(0,500),guided:Boolean(h.guided),error:typeof h.error==='string'?h.error:false};}
  out.writePending=null;
  if(g.writePending){const w=g.writePending;if(!ids.has(w.tileId)||!g.pool.includes(w.itemId))return null;out.writePending={tileId:w.tileId,itemId:w.itemId,tries:Math.max(0,Math.min(10000,Number(w.tries)||0)),answer:String(w.answer||'').slice(0,500),guided:Boolean(w.guided),error:typeof w.error==='string'?w.error:false};}
  if(g.feedback&&(!UI.it[g.feedback.key]||g.feedback.item&&!ITEM.has(g.feedback.item)))out.feedback=null;
  return out;
 }catch{return null;}
}
function validSession(g){return Boolean(sanitizeSession(g));}
function cleanSaved(p){const clean=validateProgress(p);clean.sessions={};for(const [k,g]of Object.entries(p.sessions||{}).slice(0,16)){const session=sanitizeSession(g);if(session&&k===session.route)clean.sessions[k]=session;}for(const [lang,session]of Object.entries(clean.alphabetSessions)){const lesson=ALPHABET[lang]?.lessons.find(l=>l.id===session.lesson);if(!lesson||session.queue.some(id=>!ALPHABET[lang].lessons.some(l=>l.cards.some(c=>c.id===id))))delete clean.alphabetSessions[lang];}for(const [route,tour]of Object.entries(clean.tours))if(tour.units.some(id=>!UNIT.has(id)))delete clean.tours[route];return clean;}
function freshSaved(){const p=newProgress();p.sessions={};return p;}
function load(){try{const result=loadSaved(localStorage,KEY,cleanSaved,freshSaved,['parola-mahjong-v5','parola-mahjong-v5.backup']);storageOK=result.ok;return result.value;}catch{storageOK=false;return freshSaved();}}
function save(){if(game&&view==='game')store.sessions[game.route]=game;try{storageOK=saveSafely(localStorage,KEY,store,cleanSaved);}catch{storageOK=false;}}
function t(key,vars={}){if(vars.n===1)key=({remainingPairs:'remainingPair',remainingLab:'remainingLabOne',remainingCloze:'remainingClozeOne',remainingSentences:'remainingSentence',freeCount:'freeCountOne'})[key]||key;let s=UI[store.settings.ui]?.[key];if(s==null){console.error('Missing translation',key);s=`[${key}]`;}return s.replace(/\{(\w+)\}/g,(_,k)=>vars[k]??(k==='link'?LAB_LINK[game?.target||store.settings.target]:`{${k}}`));}
function dir(l){return l==='ar'?'rtl':'ltr';}
function route(){return routeKey(store.settings);}
function missionKey(unit,mode,r=route()){return`${r}|${mode}|${mode==='compose'?'sentence_lab':mode==='picture'?'picture_words':unit}`;}
function unitItems(u){return UNIT.get(u).items.map(id=>ITEM.get(id));}
function title(u){return UNIT.get(u).title[store.settings.ui];}
