function totalXP(){return Math.floor(Object.values(store.missions).reduce((n,m)=>n+m.score,0)/10)+progressionBonus(store.daily);}
function dayActivity(day=localDay()){return store.daily[day]||(store.daily[day]={games:[],answers:[],alphabet:[],reviews:[],formats:[],bestCombo:0,challenges:{}});}
function recordIndependent(key,alphabet=false,review=false){const d=dayActivity();if(!d.answers.includes(key))d.answers.push(key);if(alphabet&&!d.alphabet.includes(key))d.alphabet.push(key);if(review&&!d.reviews.includes(key))d.reviews.push(key);}
function todaysChallenge(){const day=localDay(),saved=store.daily[day]?.challenges[route()];const known=Object.keys(store.missions).filter(k=>k.startsWith(route()+'|')&&COURSE_MODES.includes(k.split('|')[1])).map(k=>UNIT.get(k.split('|')[2])?.index??0);const pool=COURSE.units.slice(0,Math.min(COURSE.units.length,Math.max(0,...known)+3));const plan=challengePlan(day,route(),pool);return saved&&UNIT.has(saved.unit)?{...plan,unit:saved.unit,mode:saved.mode,completed:saved.completed}:plan;}
function playerStatus(){const level=playerLevel(totalXP());return `<div class="player-status"><span class="level-seal">${icon('spark',20)}${level.level}</span><div class="level-track"><strong>${esc(t('playerLevel',{n:level.level}))}<span>${totalXP()} XP</span></strong><progress max="${level.needed}" value="${level.current}" aria-label="${esc(t('nextPlayerLevel',{n:level.remaining}))}"></progress></div><span class="practice-streak">${icon('flame',18)}${practiceStreak(store.days,localDay())}<small>${esc(t('dayShort'))}</small></span></div>`;}
function goalTrail(){const goals=dailyGoals(store.daily[localDay()]),done=goals.filter(g=>g.current>=g.total).length;return `<section class="goal-trail"><div class="section-heading"><h2>${esc(t('dailyGoals'))}</h2><span>${done}/3 · ${esc(t(done===3?'goalBonusDone':'goalBonus'))}</span></div><div class="goal-list">${goals.map(g=>`<button class="goal-link ${g.current>=g.total?'is-done':''}" data-action="dailyGoal" data-goal="${g.id}"><span class="goal-symbol">${icon(g.current>=g.total?'check':g.id==='table'?'tile':g.id==='answers'?'shield':'alpha',20)}</span><span>${esc(t('goal_'+g.id))}</span><b>${Math.min(g.current,g.total)}/${g.total}</b>${icon('chevron',17)}</button>`).join('')}</div></section>`;}
