function formatControls(){
 const sentence=['complete','compose'].includes(selectedMode),picture=selectedMode==='picture',locked=pendingChallenge||pendingTour||pendingInvite||pendingTutorial||pendingReplay,original=pendingReplay?pendingReplay.tableFormat:pendingTour?TOUR_FORMATS[pendingTour.stage]:pendingInvite?pendingInvite.tableFormat:pendingTutorial?'focus':pendingChallenge?'grand':store.settings.tableFormat,selected=sentence?wordFormat(original):picture&&!['focus','classic','explorer'].includes(original)?'explorer':original,formats=sentence?['classic','grand','marathon']:picture?['focus','classic','explorer']:Object.keys(TABLE_FORMATS);
 return `<fieldset class="table-formats"><legend>${esc(t('tableSize'))}</legend><div style="--formats:${formats.length}">${formats.map(format=>{const count=sentence?wordTableSize(format):picture?Math.min(TABLE_FORMATS[format],8)*2:TABLE_FORMATS[format]*2;return `<button type="button" data-action="tableFormat" data-format="${format}" aria-label="${esc(t(picture&&format==='explorer'?'pictureFull':'format_'+format)+' · '+t('tileCount',{n:count}))}" aria-pressed="${selected===format}" ${locked?'disabled':''}><strong>${count}</strong><span>${esc(t(picture&&format==='explorer'?'pictureFull':'format_'+format))}</span></button>`;}).join('')}</div>${['grand','marathon'].includes(selected)?`<p class="format-note">${esc(t('largeTableNote'))}</p>`:''}</fieldset>`;
}

function achievementsView(){const symbols={first:'tile',mono:'globe',traveller:'path',alphabet:'alpha',writer:'write',combo:'flame',explorer:'grid',habit:'clock',tour:'path'};return `<section class="achievements"><button class="textbtn" data-action="back">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t('achievements'))}</h1><p>${esc(t('achievementsDesc'))}</p></div><ul class="achievement-list">${BADGES.map(id=>{const b=badgeProgress(store,id);return `<li class="${b.earned?'is-earned':''}"><span class="achievement-icon">${icon(symbols[id],26)}</span><div><h2>${esc(t('badge_'+id))}</h2><p>${esc(t('badge_'+id+'_desc'))}</p><progress max="${b.total}" value="${b.current}" aria-label="${esc(t('badge_'+id)+': '+b.current+'/'+b.total)}"></progress></div><span class="achievement-state">${b.earned?icon('check',22):b.current+'/'+b.total}</span></li>`;}).join('')}</ul></section>`;}

function summaryRewards(summary){const after=playerLevel(totalXP()),before=playerLevel(Math.max(0,totalXP()-summary.xp)),levelUp=after.level>before.level;return `<section class="reward-panel" aria-label="${esc(t('earnedXp'))}"><div class="reward-top"><span class="reward-xp" aria-label="+${summary.xp} XP"><span aria-hidden="true" data-reward-xp="${summary.xp}">+${summary.xp}</span><small>XP</small></span><div><strong>${esc(t(levelUp?'levelReached':'playerLevel',{n:after.level}))}</strong><p>${esc(t('nextPlayerLevel',{n:after.remaining}))}</p></div></div><div class="reward-track" role="progressbar" aria-valuemin="0" aria-valuemax="${after.needed}" aria-valuenow="${after.current}" aria-label="${esc(t('playerLevel',{n:after.level}))}"><span data-reward-fill style="transform:scaleX(${after.current/after.needed})" data-from="${levelUp?0:before.current/before.needed}" data-to="${after.current/after.needed}"></span></div>${summary.bonus?`<p class="reward-bonus">${icon('spark',17)}${esc(t('bonusEarned',{n:summary.bonus}))}</p>`:''}${summary.newBadges?.length?`<p class="reward-bonus">${icon('trophy',17)}${esc(t('newAchievement'))}: ${summary.newBadges.map(id=>esc(t('badge_'+id))).join(' · ')}</p>`:''}</section>`;}

