function adventurePanel(){const tour=store.tours[route()],active=tour&&tour.stage<3,found=collectionItems(store.memory,route(),[...COURSE.items,...COURSE.vocab]);return `<section class="adventure-panel"><div class="adventure-lead"><h2>${esc(t('tourTitle'))}</h2><p>${esc(t('tourBody'))}</p><div class="adventure-steps" aria-label="${esc(t('tourProgress'))}">${[0,1,2].map(stage=>`<span class="${active&&stage<tour.stage?'is-done':''}">${icon(active&&stage<tour.stage?'check':['pair','complete','write'][stage],20)}${esc(t('tourStep',{n:stage+1}))}</span>`).join('')}</div>${button('tour',t(active?'resumeTour':'startTour'),'path','coral')}<button class="textbtn" data-action="passport">${icon('book',19)}${esc(t('passport'))} · ${found.length}/${COURSE.items.length+COURSE.vocab.length}</button></div><div class="adventure-preview" aria-hidden="true">${unitItems(active?tour.units[tour.stage]:'greetings').map(item=>`<span lang="${store.settings.target}" dir="${dir(store.settings.target)}">${esc(item.text[store.settings.target])}</span>`).join('')}</div></section><details class="app-utilities" data-disclosure="utilities"><summary>${esc(t('moreOptions'))}${icon('down',16)}</summary><div class="app-utility-actions"><button class="textbtn" data-action="shareChallenge">${icon('globe',17)}${esc(t('challengeFriend'))}</button><button class="textbtn" data-action="installApp">${icon('download',17)}${esc(t('installApp'))}</button><a class="textbtn" href="./Parola-offline.html" download="Parola-offline.html">${icon('download',17)}${esc(t('downloadOffline'))}</a></div></details>`;}
function beginTour(){navigationSection='home';let tour=store.tours[route()];if(!tour||tour.stage===3){const reached=Object.keys(store.missions).filter(key=>key.startsWith(route()+'|')&&COURSE_MODES.includes(key.split('|')[1])).map(key=>UNIT.get(key.split('|')[2])?.index??-1),start=Math.min(COURSE.units.length-3,Math.max(-1,...reached)+1);tour={id:Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7),units:COURSE.units.slice(start,start+3).map(unit=>unit.id),stage:0,score:0};store.tours[route()]=tour;save();}const session=store.sessions[route()];if(session?.tourId===tour.id&&session.tourStage===tour.stage){resume();return;}intro(tour.units[tour.stage],TOUR_MODES[tour.stage],null,{tour});startGame();}
function tourGamePanel(){if(game?.inviteTarget!==null&&game?.inviteTarget!==undefined)return `<div class="tour-game-panel"><strong>${esc(t('inviteTitle'))}</strong><span>${esc(t('inviteGoal',{n:game.inviteTarget}))}</span></div>`;if(!game?.tourId)return '';return `<div class="tour-game-panel"><strong>${esc(t('tourTitle'))}</strong><span>${esc(t('tourStage',{n:game.tourStage+1}))}</span><progress max="3" value="${game.tourStage}" aria-label="${esc(t('tourProgress'))}"></progress></div>`;}
function tourSummary(summary){if(summary.inviteTarget!==null&&summary.inviteTarget!==undefined)return `<div class="first-win"><h2>${esc(t(summary.score>=summary.inviteTarget?'inviteWon':'inviteRetry'))}</h2><p>${esc(t('inviteResult',{score:summary.score,target:summary.inviteTarget}))}</p>${button('shareChallenge',t('challengeFriend'),'globe','coral')}</div>`;if(summary.tutorial)return `<div class="first-win"><h2>${esc(t('firstWinTitle'))}</h2><p>${esc(t('firstWinBody'))}</p>${button('tour',t('startTour'),'path','coral')}</div>`;if(!summary.tourId)return '';const tour=store.tours[summary.route],complete=tour?.stage===3;return `<div class="first-win"><h2>${esc(t(complete?'tourComplete':'tourCheckpoint'))}</h2><p>${esc(t(complete?'tourCompleteBody':'tourCheckpointBody'))}</p>${tour?`<p>${esc(t('tourTotal',{n:tour.score}))}</p>`:''}${button(complete?'passport':'tour',t(complete?'openPassport':'continueTour'),complete?'book':'path','coral')}</div>`;}
function passportView(){const all=[...COURSE.items,...COURSE.vocab].sort((a,b)=>UNIT.get(a.unitId).index-UNIT.get(b.unitId).index),found=new Set(collectionItems(store.memory,route(),all).map(item=>item.id));return `<section class="passport"><button class="textbtn" data-action="back">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t('passport'))}</h1><p>${esc(t('passportBody'))}</p><p class="passport-count">${found.size}/${all.length} · <bdi>${NAMES[store.settings.target]}</bdi></p></div><div class="passport-grid">${all.map(item=>`<article class="passport-stamp ${found.has(item.id)?'is-collected':'is-locked'}"><span>${esc(title(item.unitId))}</span>${found.has(item.id)?`<h2 lang="${store.settings.target}" dir="${dir(store.settings.target)}">${esc(item.text[store.settings.target])}</h2>${sounds(store.settings.target,item.text[store.settings.target],item.id)}`:`<div class="passport-lock">${icon('book',28)}</div><p>${esc(t('stampLocked'))}</p>`}</article>`).join('')}</div></section>`;}
function invitationPanel(){return invitation?`<section class="invitation-panel"><div><h2>${esc(t('inviteTitle'))}</h2><p>${esc(title(invitation.unit))} · ${esc(modeName(invitation.mode))} · ${esc(t('inviteScore',{n:invitation.score}))}</p></div>${button('acceptInvite',t('acceptInvite'),'play','coral')}</section>`:'';}
function acceptInvitation(){if(!invitation)return;const [support,target]=invitation.route.split('>');rememberNavigation();save();store.settings={...store.settings,support,target,ui:support===target?target:store.settings.ui};store.onboarded=true;save();intro(invitation.unit,invitation.mode,null,{invite:invitation});startGame();}
async function shareChallenge(){const plan=lastSummary&&view==='summary'?lastSummary:{...todaysChallenge(),route:route(),tableFormat:'grand',score:0};sharedLink=challengeURL('https://matteoawi.github.io/parola/',{...plan,seed:plan.seed??seedFor(localDay()+'|'+route())});if(navigator.share){try{await navigator.share({title:'Parola',text:t('shareText'),url:sharedLink});return;}catch(error){if(error.name==='AbortError')return;}}nav('share');}
function shareView(){return `<section class="share-page"><button class="textbtn" data-action="back">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t('challengeFriend'))}</h1><p>${esc(t('shareBody'))}</p></div><label for="challenge-link">${esc(t('challengeLink'))}</label><input id="challenge-link" type="url" readonly value="${esc(sharedLink)}">${button('copyChallenge',t('copyLink'),'globe','coral')}<p class="tiny-note">${esc(t('sharePrivacy'))}</p></section>`;}
async function copyChallenge(){try{await navigator.clipboard.writeText(sharedLink);toast(t('linkCopied'));}catch{const input=document.querySelector('#challenge-link');input?.focus();input?.select();toast(t('copyManually'));}}
async function installApp(){if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;return;}nav('install');}
function installView(){const installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone;return `<section class="install-page"><button class="textbtn" data-action="back">${icon('back',18,'right-arrow')}${esc(t('back'))}</button><div class="page-head"><h1>${esc(t(installed?'alreadyInstalled':'installApp'))}</h1><p>${esc(t('installBody'))}</p></div>${installPrompt?button('installApp',t('installNow'),'download','coral'):`<p>${esc(t(installed?'installedBody':'installManual'))}</p>`}<div class="offline-download"><h2>${esc(t('downloadOffline'))}</h2><p>${esc(t('offlineBody'))}</p><a class="button coral" href="./Parola-offline.html" download="Parola-offline.html">${icon('download',20)}${esc(t('downloadOffline'))}</a></div></section>`;}
function audioPackHTML(){const languages=audioPacks.selected.length?audioPacks.selected:[store.settings.target,store.settings.support];return [...new Set(languages)].map(lang=>{const state=audioPacks.states[lang];if(!state)return '';const status=state.status==='missing'?(player.voice(lang)?'packDevice':'packMissing'):state.status==='ready'?'packReady':state.status==='paused'?'packPaused':state.status==='partial'?'packPartial':'packLoading';return `<span><bdi>${esc(NAMES[lang])}</bdi> · ${esc(t(status,{n:state.loaded,total:state.total}))}</span>`;}).join('')+ (languages.some(lang=>['paused','partial'].includes(audioPacks.states[lang]?.status))?`<button class="textbtn" data-action="downloadAudio">${icon('download',16)}${esc(t('packDownload'))}</button>`:'');}
function updateAudioPack(){const status=document.querySelector('#audio-pack-status');if(status)status.innerHTML=audioPackHTML();}
function warmAudio(_items=null,force=false){return audioPacks.select([store.settings.target,store.settings.support],{force});}
function completedCount(){return Object.keys(store.missions).filter(k=>k.startsWith(route()+'|')&&COURSE_MODES.includes(k.split('|')[1])).length;}
function nextUnit(){return COURSE.units.find(u=>COURSE_MODES.some(m=>!store.missions[missionKey(u.id,m)]))||COURSE.units[0];}
function nextMode(u){return COURSE_MODES.find(m=>!store.missions[missionKey(u,m)])||'pair';}
function routeHTML(){if(store.settings.target===store.settings.support)return `<span class="langcoin target">${GLYPHS[store.settings.target]}</span><bdi>${NAMES[store.settings.target]}</bdi><span class="mono-tag">${esc(t('mono'))}</span>`;return `<span class="langcoin">${GLYPHS[store.settings.support]}</span><bdi>${NAMES[store.settings.support]}</bdi>${icon('arrow',16,'right-arrow')}<span class="langcoin target">${GLYPHS[store.settings.target]}</span><bdi>${NAMES[store.settings.target]}</bdi>`;}
function button(action,label,ico='arrow',cls='',attrs=''){return `<button class="button ${cls}" data-action="${action}" ${attrs}>${esc(label)}${icon(ico,19,'right-arrow')}</button>`;}
function sounds(lang,text,context='',slow=true){return `<div class="audio-buttons"><button class="sound" data-action="speak" data-lang="${lang}" data-text="${esc(text)}" data-context="${esc(context)}" title="${esc(t('listen'))}" aria-label="${esc(t('listen')+': '+text)}">${icon('speaker',19)}</button>${slow?`<button class="sound slow" data-action="speak" data-lang="${lang}" data-text="${esc(text)}" data-context="${esc(context)}" data-rate="0.8" title="${esc(t('slow'))}" aria-label="${esc(t('slow')+': '+text)}">${esc(t('slowRate'))}</button>`:''}</div>`;}
const player=new AudioPlayer(MANIFEST,AUDIO,key=>toast(t(key),true),{choices:()=>store.settings.deviceVoices||{},pronunciations:PRONUNCIATIONS,onVoices:updateVoiceSettings,onActivity:active=>{effects.setSpeechActive(active);updateVoiceStatus();}});
let audioStatusFrame=0;const audioPacks=new AudioPacks(MANIFEST,player,{embedded:AUDIO,cacheName:'parola-v6:'+new URL('./',location.href).pathname+':'+VERSION,notify:()=>{if(!audioStatusFrame)audioStatusFrame=requestAnimationFrame(()=>{audioStatusFrame=0;updateAudioPack();});}});
function toast(msg,warn=false){clearTimeout(toastTimer);document.querySelector('.toast')?.remove();const e=document.createElement('div');e.className='toast'+(warn?' warn':'');e.role='status';e.textContent=msg;document.body.append(e);announcer.textContent=msg;toastTimer=setTimeout(()=>e.remove(),warn?6500:3400);}
function tileFeedback(ids,kind){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;for(const tile of document.querySelectorAll('.board .tile:not(.gone)'))if(ids.includes(+tile.dataset.id)||!ids.length&&tile.classList.contains('selected'))tile.animate(reduced?[{opacity:.65},{opacity:1}]:[{transform:'translateX(0)'},{transform:'translateX(-3px)',offset:.25},{transform:'translateX(3px)',offset:.5},{transform:'translateX(0)'}],{duration:180,easing:'ease-out'});}
function fx(cue='match'){effects.play(cue===true?'match':cue===false?'error':cue);}
function celebrate(){fx('win');if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const e=document.createElement('div');e.className='confetti';e.innerHTML=Array.from({length:27},(_,i)=>`<i style="left:${(i*37)%100}%;animation-delay:${(i%6)*.08}s;transform:rotate(${i*29}deg)"></i>`).join('');document.body.append(e);setTimeout(()=>e.remove(),2700);}
// History stores small, in-memory screen contexts; learning progress remains in storage.
function navigationKey(){return [view,route(),view==='intro'?selectedUnit:'',view==='alphaLesson'?alphaLessonId:''].join('|');}
function navigationSnapshot(){const focused=document.activeElement;return {key:navigationKey(),view,route:route(),navigationSection,homeTab,settingsTab,selectedUnit,selectedMode,alphaLessonId,pendingChallenge,pendingTour,pendingInvite,pendingTutorial,pendingReplay,preparation,lastSummary,sharedLink,gameId:game?.id,scrollY:window.scrollY,focus:focused?.dataset?.action?Object.fromEntries(Object.entries(focused.dataset).filter(([key])=>['action','view','unit','lesson','tab'].includes(key))):null};}
function rememberNavigation(){const entry=navigationEntries.get(navigationId);if(entry&&entry.key===navigationKey())Object.assign(entry,navigationSnapshot());}
function syncNavigation(previousView){
 const current=navigationEntries.get(navigationId),snapshot=navigationSnapshot();
 if(restoringNavigation){if(current)Object.assign(current,snapshot,{scrollY:current.scrollY,focus:current.focus});return;}
 if(current?.key===snapshot.key){Object.assign(current,snapshot,{scrollY:current.scrollY,focus:current.focus});return;}
 const replace=(!current)||(previousView==='prepare'&&['game','alphaQuiz'].includes(view))||(previousView==='game'&&view==='summary')||(previousView==='welcome'&&store.onboarded);
 const parentId=replace?current?.parentId??null:navigationId;navigationId=++navigationSerial;
 navigationEntries.set(navigationId,{...snapshot,parentId});
 history[replace?'replaceState':'pushState']({parolaNavigation:navigationId,parolaDocument:navigationToken},'');
 if(navigationEntries.size>100)navigationEntries.delete(navigationEntries.keys().next().value);
}
function back(){const entry=navigationEntries.get(navigationId);if(entry?.parentId&&navigationEntries.has(entry.parentId))history.back();else nav('home');}
addEventListener('popstate',event=>{
 rememberNavigation();save();player.stop();closeDialog();document.querySelector('.confetti')?.remove();
 const sameDocument=event.state?.parolaDocument===navigationToken,entry=sameDocument?navigationEntries.get(event.state.parolaNavigation):null;navigationId=sameDocument?event.state.parolaNavigation:0;restoringNavigation=true;
 try{
  game=null;preparation=null;pendingChallenge=null;pendingTour=null;pendingInvite=null;pendingTutorial=false;pendingReplay=null;
  if(entry&&entry.route===route()&&entry.view!=='welcome'){
   ({view,navigationSection,homeTab,settingsTab,selectedUnit,selectedMode,alphaLessonId,pendingChallenge,pendingTour,pendingInvite,pendingTutorial,pendingReplay,lastSummary,sharedLink}=entry);
   if(view==='game'){const session=sanitizeSession(store.sessions[route()]);if(session?.id===entry.gameId)prepareGame(session);else{view='home';render();}}
   else if(view==='prepare'){if(entry.preparation?.kind==='game')prepareGame(entry.preparation.draft);else if(store.alphabetSessions[store.settings.target]?.lesson===entry.alphaLessonId)prepareAlphabet();else{view='alphaLesson';render();}}
   else if(view==='alphaQuiz'){if(store.alphabetSessions[store.settings.target]?.lesson===entry.alphaLessonId)prepareAlphabet();else{view='alphaLesson';render();}}
   else render();
   window.scrollTo({top:entry.scrollY||0,behavior:'instant'});
   const focus=entry.focus&&[...root.querySelectorAll('[data-action]')].find(el=>Object.entries(entry.focus).every(([key,value])=>el.dataset[key]===value));focus?.focus({preventScroll:true});
  }else{view=store.onboarded?'home':'welcome';navigationSection='home';render();window.scrollTo({top:0,behavior:'instant'});}
 }finally{restoringNavigation=false;}
});
function nav(action){if(action==='settings')settingsTab='languages';rememberNavigation();save();player.stop();if(['home','play','review','notebook','settings'].includes(action))navigationSection=action;preparation=null;pendingChallenge=null;pendingTour=null;pendingInvite=null;pendingTutorial=false;pendingReplay=null;document.querySelector('.confetti')?.remove();closeDialog();view=action;game=null;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){
 const previousInterface=captureInterface(root),sameView=renderedView===view;
 document.body.dataset.screen=view;document.body.dataset.settingsTab=settingsTab;document.documentElement.lang=store.settings.ui;document.documentElement.dir=dir(store.settings.ui);document.body.classList.toggle('in-game',view==='game'||view==='alphaQuiz'&&store.alphabetSessions[store.settings.target]?.index<store.alphabetSessions[store.settings.target]?.queue.length);document.body.classList.toggle('in-preparation',view==='prepare');document.body.classList.toggle('large',store.settings.large);document.body.classList.toggle('mono',store.settings.support===store.settings.target);
 const activeNav=['home','play','review','notebook','settings'].includes(view)?view:navigationSection;
 if(sameView&&['game','alphaQuiz'].includes(view))reconcileGame(root,view==='game'?gameView():alphabetQuizView());else root.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('tile',24)}</span><span>parola<span class="dot">.</span></span></div><nav class="nav" aria-label="${esc(t('path'))}">${[['home','play'],['play','grid'],['review','review'],['notebook','book'],['settings','settings']].map(([v,i])=>`<button class="navbtn ${activeNav===v?'current':''}" data-action="nav" data-view="${v}" ${activeNav===v?'aria-current="page"':''} title="${esc(t('nav_'+v))}" aria-label="${esc(t('nav_'+v))}">${icon(i,23)}<span>${esc(t('nav_'+v))}</span></button>`).join('')}</nav><div class="sidebase"><div class="mini-mascot"><i class="eye"></i><i class="eye"></i></div><p>${esc(t('noHearts'))}</p></div></aside><main class="main"><header class="topbar"><span class="mobile-brand" aria-label="Parola">parola<span>.</span></span><button class="routebtn" data-action="nav" data-view="settings" aria-label="${esc(t('settings'))}">${routeHTML()}${icon('down',15)}</button><div class="topstats"><span class="topstat flame" title="${esc(t('streakDays'))}">${icon('flame',23)}${practiceStreak(store.days,localDay())}</span><span class="topstat xp">${icon('spark',23)}${totalXP()} <small>XP</small></span><button class="profile" data-action="nav" data-view="settings" aria-label="${esc(t('uiLanguage'))}">${GLYPHS[store.settings.ui]}</button></div></header><div id="audio-pack-status" class="audio-pack-status" aria-label="${esc(t('audioTitle'))}">${audioPackHTML()}</div><div id="view">${({prepare:preparationView,welcome:welcomeView,home:homeView,play:playView,intro:introView,game:gameView,summary:summaryView,settings:settingsView,review:reviewView,notebook:notebookView,achievements:achievementsView,passport:passportView,install:installView,share:shareView,alphabet:alphabetView,alphaLesson:alphabetLessonView,alphaQuiz:alphabetQuizView}[view]||homeView)()}</div>${!storageOK?`<div class="note-warning">${esc(t('saveError'))}</div>`:''}<footer class="footer"><span>PAROLA / ${esc(VERSION)} · ${esc(t('brandTag'))}</span><span>${esc(t('buildInfo'))} · <a href="./changelog.html">${esc(t('releaseNotes'))}</a> · <a href="./credits.html">${esc(t('iconCredits'))}</a></span></footer></main></div>`;
 if(view==='alphaQuiz'){sizeBoard();save();}
  if(view==='game'){sizeBoard();save();if(game?.helpPending)openHelpDialog();else if(game?.writePending)openWriteDialog();}
 restoreInterface(root,previousInterface,sameView);syncNavigation(renderedView);if(!sameView&&!restoringNavigation){const heading=root.querySelector('.home-panel.is-active h1')||root.querySelector('#view h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}}renderedView=view;updateKeyboardSend();if(store.onboarded)warmAudio();
}
function art(){return `<div class="hero-art" aria-hidden="true"><div class="hero-blob"></div><div class="art-spark">✧</div><div class="tilefriend"><i class="eye"></i><i class="eye"></i><i class="cheek"></i><i class="cheek"></i></div><span class="floatword a">ciao!</span><span class="floatword b">hello!</span><span class="floatword c" lang="ar">مرحبًا</span><span class="floatword d" lang="ru">привет!</span></div>`;}
function unitCard(u){const done=COURSE_MODES.filter(m=>store.missions[missionKey(u.id,m)]).length;return `<button class="unitcard ${nextUnit().id===u.id?'recommended':''}" data-action="intro" data-unit="${u.id}" aria-label="${esc(t('unit',{n:u.index+1})+': '+title(u.id))}"><span class="unitnum">${done===COURSE_MODES.length?icon('check',24):String(u.index+1).padStart(2,'0')}</span><span class="unittext"><h3>${esc(title(u.id))}</h3><span class="minimodes">${COURSE_MODES.map(m=>`<span class="modedot ${store.missions[missionKey(u.id,m)]?'done':''}" title="${esc(modeName(m))}">${icon(store.missions[missionKey(u.id,m)]?'check':modeIcon(m),12)}</span>`).join('')}</span></span>${icon('chevron',21,'unittrail')}</button>`;}
function courseList(){return COURSE.chapters.map((c,j)=>{const units=COURSE.units.filter(u=>u.chapter===j),done=units.reduce((n,u)=>n+COURSE_MODES.filter(m=>store.missions[missionKey(u.id,m)]).length,0),total=units.length*COURSE_MODES.length;return `<details class="course-chapter" ${nextUnit().chapter===j?'open':''} data-disclosure="chapter_${j}"><summary><div class="chapter-header"><span class="chapter-icon">${icon(['spark','globe','book','tile'][j],21)}</span><div><h3>${esc(c[store.settings.ui])}</h3><span>${done}/${total} ${esc(t('missionsShort'))}</span></div>${icon('down',18)}</div></summary><div class="units">${units.map(unitCard).join('')}</div></details>`;}).join('');}

function homeView(){const u=nextUnit();return `<div class="home-tabs" role="tablist" style="--tab:${['play','learn','today'].indexOf(homeTab)}" aria-label="${esc(t('homeSections'))}">${['play','learn','today'].map(tab=>`<button role="tab" id="home-tab-${tab}" data-action="homeTab" data-tab="${tab}" aria-controls="home-panel-${tab}" aria-selected="${homeTab===tab}" tabindex="${homeTab===tab?0:-1}">${esc(t('home_'+tab))}</button>`).join('')}</div>${invitationPanel()}<section id="home-panel-play" class="home-panel ${homeTab==='play'?'is-active':''}" data-home-panel="play" role="tabpanel" aria-labelledby="home-tab-play">${playerStatus()}${nextTableHero()}${mobilePlayActions()}${goalTrail()}${dailyPlayLink()}<details class="home-more" data-disclosure="play-more"><summary>${esc(t('moreAdventures'))}${icon('down',18)}</summary>${adventurePanel()}</details></section><section id="home-panel-today" class="home-panel ${homeTab==='today'?'is-active':''}" data-home-panel="today" role="tabpanel" aria-labelledby="home-tab-today">${progressionPanel()}</section><section id="home-panel-learn" class="home-panel ${homeTab==='learn'?'is-active':''}" data-home-panel="learn" role="tabpanel" aria-labelledby="home-tab-learn"><div class="page-head"><h1>${esc(t('learnTitle'))}</h1><p>${esc(t('learnLead'))}</p></div>${learningEntry()}<div class="section-heading"><h2>${esc(t('phrasePath'))}</h2><span>${completedCount()}/${COURSE.units.length*COURSE_MODES.length}</span></div>${courseList()}<button class="textbtn" data-action="nav" data-view="notebook">${icon('book',19)}${esc(t('openNotebook'))}${icon('arrow',17)}</button></section>`;}
