function pairPool(unit,count=6,random=Math.random){const current=unitItems(unit),u=UNIT.get(unit);if(count===3)return current;const previous=COURSE.items.filter(i=>UNIT.get(i.unitId).index<u.index);const extras=previous.length?previous.slice(-3):COURSE.vocab.slice(0,3);const candidates=[...current,...extras,...shuffled(previous,random),...COURSE.vocab,...COURSE.items.filter(i=>UNIT.get(i.unitId).index>u.index)];return [...new Map(candidates.map(i=>[i.id,i])).values()].slice(0,count);}
