document.addEventListener('keydown',e=>{const tab=e.target.closest('[data-action=homeTab],[data-action=settingsTab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...root.querySelectorAll('[data-action='+tab.dataset.action+']')],index=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)*(document.documentElement.dir==='rtl'?-1:1)+tabs.length)%tabs.length;if(tab.dataset.action==='settingsTab')switchSettingsTab(tabs[next].dataset.tab);else switchHomeTab(tabs[next].dataset.tab);tabs[next].focus();return;}const tile=e.target.closest('.tile');if(tile&&!e.target.closest('.tileaudio')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const origin=tile.getBoundingClientRect(),axis=e.key==='ArrowLeft'||e.key==='ArrowRight'?'x':'y',sign=e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1;const candidates=[...document.querySelectorAll('.tile[data-free=true]:not(.gone)')].filter(el=>el!==tile).map(el=>{const r=el.getBoundingClientRect(),dx=r.x-origin.x,dy=r.y-origin.y;return{el,distance:Math.abs(axis==='x'?dx:dy)+Math.abs(axis==='x'?dy:dx)*3,direction:(axis==='x'?dx:dy)*sign}}).filter(c=>c.direction>1).sort((a,b)=>a.distance-b.distance);candidates[0]?.el.focus({preventScroll:true});candidates[0]?.el.scrollIntoView({block:'nearest',inline:'nearest'});return;}if(tile&&!e.target.closest('.tileaudio')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();if(tile.dataset.action==='alphaTile')pickAlphabetTile(+tile.dataset.id);else pickTile(+tile.dataset.id);}if(e.target.id==='alpha-answer'&&e.key==='Enter'&&!e.isComposing){e.preventDefault();checkAlphabet();}if(e.target.id==='write-answer'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();checkWrite();}if(e.target.id==='help-answer'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();checkHelp();}});
document.addEventListener('change',e=>{const el=e.target;if(['setting-journey','setting-target'].includes(el.id))syncSettingRoute();if(['welcome-target','welcome-support','setting-target','setting-support','setting-journey'].includes(el.id)){const target=document.querySelector('#welcome-target, #setting-target')?.value||store.settings.target,support=document.querySelector('#welcome-support, #setting-support')?.value||store.settings.support;audioPacks.select([target,support]);}if(el.dataset.setting){store.settings[el.dataset.setting]=el.checked;save();}if(el.id==='voice-pref'){player.stop();store.settings.voice=el.value;store.settings.voicePreferencesVersion=1;save();updateVoiceSettings();}if(el.dataset.voiceLang){player.stop();store.settings.deviceVoices[el.dataset.voiceLang]=el.value;save();updateVoiceSettings();}if(el.id==='free-unit')selectedUnit=el.value;if(el.id==='import-file')importProgress(el.files[0]);});
